/* Generated by tools/build_lines.py from picks/g14.txt. Every line is from: NCERT XI Part 2 (old). Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("g14", "NCERT XI Part 2 (old)", [{"sec": "Occurrence","ids": [936],"t": "Group 14: C, Si, Ge, Sn, Pb.","exc": false,"tab": false,"src": "old11","page": 63,"o": "Carbon (C), silicon (Si), germanium (Ge), tin (Sn) and lead (Pb) are the members of group 14."},{"sec": "Occurrence","ids": [938],"t": "Free C: coal, graphite, diamond. Combined: carbonates, hydrocarbons, CO2 (0.03% of air).","exc": false,"tab": false,"src": "old11","page": 63,"o": "In elemental state it is available as coal, graphite and diamond; however, in combined state it is present as metal carbonates, hydrocarbons and carbon dioxide gas (0.03%) in air."},{"sec": "Occurrence","ids": [943,944],"t": "Isotopes ^12C, ^13C (stable) and ^14C (radioactive, t½ 5770 years, radiocarbon dating).","exc": false,"tab": false,"src": "old11","page": 63,"o": "Naturally occurring carbon contains two stable isotopes: ^12C and ^13C. In addition to these, third isotope, ^14C is also present. It is a radioactive isotope with half-life 5770 years and used for radiocarbon dating."},{"sec": "Occurrence","ids": [945,946],"t": "Si: second most abundant element in the crust (27.7%), as silica and silicates; key in ceramics, glass, cement.","exc": false,"tab": false,"src": "old11","page": 63,"o": "Silicon is the second (27.7 % by mass) most abundant element on the earth's crust and is present in nature in the form of silica and silicates. Silicon is a very important component of ceramics, glass and cement."},{"sec": "Occurrence","ids": [947,948],"t": "Ores: Sn as cassiterite SnO2, Pb as galena PbS. Ultrapure Ge and Si: transistors, semiconductors.","exc": false,"tab": false,"src": "old11","page": 64,"o": "Germanium exists only in traces. Tin occurs mainly as cassiterite, SnO2 and lead as galena, PbS. Ultrapure form of germanium and silicon are used to make transistors and semiconductor devices."},{"sec": "Atomic and physical properties","ids": [949],"t": "ns^2np^2.","exc": false,"tab": false,"src": "old11","page": 64,"o": "The valence shell electronic configuration of these elements is ns^2np^2."},{"sec": "Atomic and physical properties","ids": [951,952],"t": "**Big radius jump C → Si, then only small increases Si → Pb** (filled d and f orbitals).","exc": true,"tab": false,"src": "old11","page": 64,"o": "There is a considerable increase in covalent radius from C to Si, thereafter from Si to Pb a small increase in radius is observed. This is due to the presence of completely filled d and f orbitals in heavier members."},{"sec": "Atomic and physical properties","ids": [953,955],"t": "∆iH1 higher than group 13; generally decreases down the group.","exc": false,"tab": false,"src": "old11","page": 64,"o": "The first ionization enthalpy of group 14 members is higher than the corresponding members of group 13. In general the ionisation enthalpy decreases down the group."},{"sec": "Atomic and physical properties","ids": [956],"t": "**∆iH: small decrease Si → Ge → Sn, slight increase Sn → Pb** (poor d/f shielding, size).","exc": true,"tab": false,"src": "old11","page": 64,"o": "Small decrease in ∆iH from Si to Ge to Sn and slight increase in ∆iH from Sn to Pb is the consequence of poor shielding effect of intervening d and f orbitals and increase in size of the atom."},{"sec": "Atomic and physical properties","ids": [957,958],"t": "Slightly more electronegative than group 13; EN of Si to Pb almost equal.","exc": false,"tab": false,"src": "old11","page": 64,"o": "Due to small size, the elements of this group are slightly more electronegative than group 13 elements. The electronegativity values for elements from Si to Pb are almost the same."},{"sec": "Atomic and physical properties","ids": [959,960,961],"t": "All solids. C, Si non-metals; Ge metalloid; Sn, Pb soft low-melting metals.","exc": false,"tab": false,"src": "old11","page": 64,"o": "All group 14 members are solids. Carbon and silicon are non-metals, germanium is a metalloid, whereas tin and lead are soft metals with low melting points."},{"sec": "Atomic and physical properties","ids": [960],"t": "Table 11.2 (group 14): ∆iH1/kJ mol^-1 C 1086, Si 786, Ge 761, Sn 708, Pb 715. Covalent radius/pm 77, 118, 122, 140, 146. Electronegativity 2.5, 1.8, 1.8, 1.8, 1.9. Melting point/K 4373, 1693, 1218, 505, 600.","exc": false,"tab": true,"src": "old11","page": 64,"o": "Table 11.2 (group 14): ∆iH1/kJ mol^-1 C 1086, Si 786, Ge 761, Sn 708, Pb 715. Covalent radius/pm 77, 118, 122, 140, 146. Electronegativity 2.5, 1.8, 1.8, 1.8, 1.9. Melting point/K 4373, 1693, 1218, 505, 600."},{"sec": "Atomic and physical properties","ids": [962],"t": "m.p./b.p. much higher than group 13.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Melting points and boiling points of group 14 elements are much higher than those of corresponding elements of group 13."},{"sec": "Oxidation states","ids": [962,963,964],"t": "Common oxidation states +4, +2; C also negative.","exc": false,"tab": false,"src": "old11","page": 65,"o": "The group 14 elements have four electrons in outermost shell. The common oxidation states exhibited by these elements are +4 and +2. Carbon also exhibits negative oxidation states."},{"sec": "Oxidation states","ids": [965],"t": "Very high sum of first four ∆iH, so +4 compounds are generally covalent.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Since the sum of the first four ionization enthalpies is very high, compounds in +4 oxidation state are generally covalent in nature."},{"sec": "Oxidation states","ids": [966,967],"t": "+2 tendency rises Ge < Sn < Pb (inert pair: ns^2 reluctant to bond).","exc": false,"tab": false,"src": "old11","page": 65,"o": "In heavier members the tendency to show +2 oxidation state increases in the sequence Ge<Sn<Pb. It is due to the inability of ns^2 electrons of valence shell to participate in bonding."},{"sec": "Oxidation states","ids": [969,970],"t": "C and Si mostly +4; Ge stable +4, few +2 compounds.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Carbon and silicon mostly show +4 oxidation state. Germanium forms stable compounds in +4 state and only few compounds in +2 state."},{"sec": "Oxidation states","ids": [971,972],"t": "**Sn(II) is a reducing agent; Pb(II) is stable and Pb(IV) a strong oxidant.**","exc": true,"tab": false,"src": "old11","page": 65,"o": "Tin forms compounds in both oxidation states (Sn in +2 state is a reducing agent). Lead compounds in +2 state are stable and in +4 state are strong oxidising agents."},{"sec": "Oxidation states","ids": [973,974],"t": "+4 molecules (e.g. CCl4) are electron precise: normally neither electron acceptors nor donors.","exc": false,"tab": false,"src": "old11","page": 65,"o": "In tetravalent state the number of electrons around the central atom in a molecule (e.g., carbon in CCl4) is eight. Being electron precise molecules, they are normally not expected to act as electron acceptor or electron donor species."},{"sec": "Oxidation states","ids": [975,976,977],"t": "C can't exceed covalence 4; others can (d orbitals), so their halides hydrolyse and form complexes with donors.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Although carbon cannot exceed its covalence more than 4, other elements of the group can do so. It is because of the presence of d orbital in them. Due to this, their halides undergo hydrolysis and have tendency to form complexes by accepting electron pairs from donor species."},{"sec": "Oxidation states","ids": [978],"t": "SiF6^2-, [GeCl6]^2-, [Sn(OH)6]^2-: central atom sp^3d^2.","exc": false,"tab": false,"src": "old11","page": 65,"o": "For example, the species like, SiF6^2-, [GeCl6]^2-, [Sn(OH)6]^2- exist where the hybridisation of the central atom is sp^3d^2."},{"sec": "Oxides, water, halides","ids": [978,979,980],"t": "Oxides MO and MO2; **SiO exists only at high temperature**.","exc": true,"tab": false,"src": "old11","page": 65,"o": "All members when heated in oxygen form oxides. There are mainly two types of oxides, i.e., monoxide and dioxide of formula MO and MO2 respectively. SiO only exists at high temperature."},{"sec": "Oxides, water, halides","ids": [981,982],"t": "Higher oxidation state oxides are more acidic. **CO2, SiO2, GeO2 acidic; SnO2, PbO2 amphoteric.**","exc": true,"tab": false,"src": "old11","page": 65,"o": "Oxides in higher oxidation states of elements are generally more acidic than those in lower oxidation states. The dioxides — CO2, SiO2 and GeO2 are acidic, whereas SnO2 and PbO2 are amphoteric in nature."},{"sec": "Oxides, water, halides","ids": [983],"t": "**Monoxides: CO neutral, GeO distinctly acidic, SnO and PbO amphoteric.**","exc": true,"tab": false,"src": "old11","page": 65,"o": "Among monoxides, CO is neutral, GeO is distinctly acidic whereas SnO and PbO are amphoteric."},{"sec": "Oxides, water, halides","ids": [984,985],"t": "Most acidic dioxide: C. Commonly +2: Pb. Semiconductors: Si, Ge.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Problem 11.5: Select the member(s) of group 14 that (i) forms the most acidic dioxide, (ii) is commonly found in +2 oxidation state, (iii) used as semiconductor. Answer: (i) carbon (ii) lead (iii) silicon and germanium."},{"sec": "Oxides, water, halides","ids": [985,986,987],"t": "C, Si, Ge unaffected by water; **Sn decomposes steam**: Sn + 2H2O → SnO2 + 2H2","exc": false,"tab": false,"src": "old11","page": 65,"o": "Carbon, silicon and germanium are not affected by water. Tin decomposes steam to form dioxide and dihydrogen gas. Sn + 2H2O → SnO2 + 2H2 (∆)"},{"sec": "Oxides, water, halides","ids": [987],"t": "Pb is unaffected by water (protective oxide film).","exc": true,"tab": false,"src": "old11","page": 65,"o": "Lead is unaffected by water, probably because of a protective oxide film formation."},{"sec": "Oxides, water, halides","ids": [988,989],"t": "Halides MX2 and MX4; all except C react directly with halogens.","exc": false,"tab": false,"src": "old11","page": 65,"o": "These elements can form halides of formula MX2 and MX4 (where X = F, Cl, Br, I). Except carbon, all other members react directly with halogen under suitable condition to make halides."},{"sec": "Oxides, water, halides","ids": [990,991,992],"t": "MX4: mostly covalent, sp^3, tetrahedral; **SnF4 and PbF4 are ionic**.","exc": true,"tab": false,"src": "old11","page": 65,"o": "Most of the MX4 are covalent in nature. The central metal atom in these halides undergoes sp^3 hybridisation and the molecule is tetrahedral in shape. Exceptions are SnF4 and PbF4, which are ionic in nature."},{"sec": "Oxides, water, halides","ids": [993],"t": "**PbI4 does not exist**: Pb–I bond formation doesn't release enough energy to unpair 6s^2.","exc": true,"tab": false,"src": "old11","page": 65,"o": "PbI4 does not exist because Pb—I bond initially formed during the reaction does not release enough energy to unpair 6s^2 electrons and excite one of them to higher orbital to have four unpaired electrons around lead atom."},{"sec": "Oxides, water, halides","ids": [994,995,996],"t": "Ge to Pb form MX2; dihalide stability increases down the group: GeX4 > GeX2, but PbX2 > PbX4.","exc": false,"tab": false,"src": "old11","page": 65,"o": "Heavier members Ge to Pb are able to make halides of formula MX2. Stability of dihalides increases down the group. Considering the thermal and chemical stability, GeX4 is more stable than GeX2, whereas PbX2 is more than PbX4."},{"sec": "Oxides, water, halides","ids": [997,998],"t": "**All tetrachlorides except CCl4 hydrolyse easily**: the central atom accepts the O lone pair into a d orbital.","exc": true,"tab": false,"src": "old11","page": 65,"o": "Except CCl4, other tetrachlorides are easily hydrolysed by water because the central atom can accommodate the lone pair of electrons from oxygen atom of water molecule in d orbital."},{"sec": "Oxides, water, halides","ids": [998],"t": "SiCl4 + 4H2O → Si(OH)4 (silicic acid) + 4HCl","exc": false,"tab": true,"src": "old11","page": 66,"o": "SiCl4 + 4H2O → Si(OH)4 (silicic acid) + 4HCl"},{"sec": "Oxides, water, halides","ids": [998,1000,1001],"t": "**[SiF6]^2- exists, [SiCl6]^2- doesn't**: six large Cl^- can't fit around Si^4+, and the Cl^- lone pair–Si^4+ interaction is weak.","exc": true,"tab": false,"src": "old11","page": 66,"o": "[SiF6]^2- is known whereas [SiCl6]^2- not. The main reasons are: (i) six large chloride ions cannot be accommodated around Si^4+ due to limitation of its size. (ii) interaction between lone pair of chloride ion and Si^4+ is not very strong."},{"sec": "Anomalous behaviour of carbon","ids": [1002,1003],"t": "C is anomalous: smaller size, higher EN and ∆iH, no d orbitals.","exc": true,"tab": false,"src": "old11","page": 66,"o": "Like first member of other groups, carbon also differs from rest of the members of its group. It is due to its smaller size, higher electronegativity, higher ionisation enthalpy and unavailability of d orbitals."},{"sec": "Anomalous behaviour of carbon","ids": [1004,1005],"t": "C: only s and p orbitals, max four electron pairs, so max covalence 4; others can expand.","exc": false,"tab": false,"src": "old11","page": 66,"o": "In carbon, only s and p orbitals are available for bonding and, therefore, it can accommodate only four pairs of electrons around it. This would limit the maximum covalence to four whereas other members can expand their covalence due to the presence of d orbitals."},{"sec": "Anomalous behaviour of carbon","ids": [1006,1007],"t": "C forms pπ–pπ multiple bonds with itself and small electronegative atoms (C=C, C≡C, C=O, C=S, C≡N); heavier atoms' orbitals are too large and diffuse.","exc": false,"tab": false,"src": "old11","page": 66,"o": "Carbon also has unique ability to form pπ-pπ multiple bonds with itself and with other atoms of small size and high electronegativity. Few examples of multiple bonding are: C=C, C≡C, C=O, C=S, and C≡N. Heavier elements do not form pπ-pπ bonds because their atomic orbitals are too large and diffuse to have effective overlapping."},{"sec": "Anomalous behaviour of carbon","ids": [1008,1009,1010],"t": "Catenation: C forms chains and rings (strong C–C bonds).","exc": false,"tab": false,"src": "old11","page": 66,"o": "Carbon atoms have the tendency to link with one another through covalent bonds to form chains and rings. This property is called catenation. This is because C—C bonds are very strong."},{"sec": "Anomalous behaviour of carbon","ids": [1011,1013],"t": "**Catenation: C >> Si > Ge ≈ Sn; Pb shows none.**","exc": true,"tab": false,"src": "old11","page": 66,"o": "Down the group the size increases and electronegativity decreases, and, thereby, tendency to show catenation decreases. The order of catenation is C >> Si > Ge ≈ Sn. Lead does not show catenation."},{"sec": "Anomalous behaviour of carbon","ids": [1014],"t": "Bond enthalpy/kJ mol^-1: C—C 348, Si—Si 297, Ge—Ge 260, Sn—Sn 240.","exc": false,"tab": true,"src": "old11","page": 66,"o": "Bond enthalpy/kJ mol^-1: C—C 348, Si—Si 297, Ge—Ge 260, Sn—Sn 240."},{"sec": "Allotropes of carbon","ids": [1014,1015,1016],"t": "Catenation and pπ–pπ bonding give C many crystalline and amorphous allotropes; diamond and graphite are crystalline.","exc": false,"tab": false,"src": "old11","page": 66,"o": "Due to property of catenation and pπ-pπ bond formation, carbon is able to show allotropic forms. Carbon exhibits many allotropic forms; both crystalline as well as amorphous. Diamond and graphite are two well-known crystalline forms of carbon."},{"sec": "Allotropes of carbon","ids": [1017,1018],"t": "Third crystalline form: fullerenes.","exc": false,"tab": false,"src": "old11","page": 66,"o": "In 1985, third form of carbon known as fullerenes was discovered by H.W.Kroto, E.Smalley and R.F.Curl. For this discovery they were awarded the Nobel Prize in 1996."},{"sec": "Allotropes of carbon","ids": [1020,1021],"t": "Diamond: each C sp^3, bonded tetrahedrally to four C; C–C 154 pm.","exc": false,"tab": false,"src": "old11","page": 66,"o": "In diamond each carbon atom undergoes sp^3 hybridisation and linked to four other carbon atoms by using hybridised orbitals in tetrahedral fashion. The C-C bond length is 154 pm."},{"sec": "Allotropes of carbon","ids": [1022,1024,1025],"t": "Rigid 3D network of directional covalent bonds, so diamond is the hardest substance.","exc": false,"tab": false,"src": "old11","page": 66,"o": "The structure extends in space and produces a rigid three-dimensional network of carbon atoms. In this structure directional covalent bonds are present throughout the lattice. It is very difficult to break extended covalent bonding and, therefore, diamond is a hardest substance on the earth."},{"sec": "Allotropes of carbon","ids": [1026],"t": "Diamond uses: abrasive, dies, making tungsten filaments.","exc": false,"tab": false,"src": "old11","page": 67,"o": "It is used as an abrasive for sharpening hard tools, in making dies and in the manufacture of tungsten filaments for electric light bulbs."},{"sec": "Allotropes of carbon","ids": [1029,1030],"t": "Graphite: layers held by van der Waals forces, 340 pm apart.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Graphite has layered structure. Layers are held by van der Waals forces and distance between two layers is 340 pm."},{"sec": "Allotropes of carbon","ids": [1031,1032],"t": "Each layer: planar hexagonal rings; C–C 141.5 pm.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Each layer is composed of planar hexagonal rings of carbon atoms. C—C bond length within the layer is 141.5 pm."},{"sec": "Allotropes of carbon","ids": [1033,1034,1035],"t": "Each C sp^2 with three σ bonds; fourth electron forms delocalised π bonding over the sheet.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Each carbon atom in hexagonal ring undergoes sp^2 hybridisation and makes three sigma bonds with three neighbouring carbon atoms. Fourth electron forms a π bond. The electrons are delocalised over the whole sheet."},{"sec": "Allotropes of carbon","ids": [1036],"t": "Graphite conducts along the sheet (mobile electrons).","exc": false,"tab": false,"src": "old11","page": 67,"o": "Electrons are mobile and, therefore, graphite conducts electricity along the sheet."},{"sec": "Allotropes of carbon","ids": [1037,1038],"t": "Cleaves between layers, soft and slippery: **dry lubricant at high temperature** where oil can't be used.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Graphite cleaves easily between the layers and, therefore, it is very soft and slippery. For this reason graphite is used as a dry lubricant in machines running at high temperature, where oil cannot be used as a lubricant."},{"sec": "Allotropes of carbon","ids": [1038],"t": "Fullerenes: heat graphite in an electric arc under He or Ar.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Fullerenes are made by the heating of graphite in an electric arc in the presence of inert gases such as helium or argon."},{"sec": "Allotropes of carbon","ids": [1039],"t": "Soot is mainly C60, less C70, traces of even-numbered fullerenes up to C350+.","exc": false,"tab": false,"src": "old11","page": 67,"o": "The sooty material formed by condensation of vapourised Cn small molecules consists of mainly C60 with smaller quantity of C70 and traces of fullerenes consisting of even number of carbon atoms up to 350 or above."},{"sec": "Allotropes of carbon","ids": [1040],"t": "**Fullerenes are the only pure form of carbon** (smooth, no dangling bonds).","exc": true,"tab": false,"src": "old11","page": 67,"o": "Fullerenes are the only pure form of carbon because they have smooth structure without having 'dangling' bonds."},{"sec": "Allotropes of carbon","ids": [1041,1042],"t": "Cage molecules; C60 (soccer-ball shape) = Buckminsterfullerene.","exc": false,"tab": false,"src": "old11","page": 67,"o": "Fullerenes are cage like molecules. C60 molecule has a shape like soccer ball and called Buckminsterfullerene."},{"sec": "Allotropes of carbon","ids": [1043,1044],"t": "C60: 20 six-membered and 12 five-membered rings; a 5-ring fuses only with 6-rings.","exc": false,"tab": false,"src": "old11","page": 67,"o": "It contains twenty six-membered rings and twelve five membered rings. A six membered ring is fused with six or five membered rings but a five membered ring can only fuse with six membered rings."},{"sec": "Allotropes of carbon","ids": [1045,1046,1047,1048],"t": "All C equivalent, sp^2; three σ bonds each; remaining electrons delocalised, so aromatic.","exc": false,"tab": false,"src": "old11","page": 67,"o": "All the carbon atoms are equal and they undergo sp^2 hybridisation. Each carbon atom forms three sigma bonds with other three carbon atoms. The remaining electron at each carbon is delocalised in molecular orbitals, which in turn give aromatic character to molecule."},{"sec": "Allotropes of carbon","ids": [1049],"t": "60 vertices; single and double bonds: C–C 143.5 pm and 138.3 pm.","exc": false,"tab": false,"src": "old11","page": 68,"o": "This ball shaped molecule has 60 vertices and each one is occupied by one carbon atom and it also contains both single and double bonds with C-C distances of 143.5 pm and 138.3 pm respectively."},{"sec": "Allotropes of carbon","ids": [1050],"t": "Spherical fullerenes = bucky balls.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Spherical fullerenes are also called bucky balls in short."},{"sec": "Allotropes of carbon","ids": [1052,1053],"t": "**Graphite is the thermodynamically most stable allotrope (∆fH° = 0)**; diamond 1.90, C60 38.1 kJ mol^-1.","exc": true,"tab": false,"src": "old11","page": 68,"o": "It is very important to know that graphite is thermodynamically most stable allotrope of carbon and, therefore, ∆fH° of graphite is taken as zero. ∆fH° values of diamond and fullerene, C60, are 1.90 and 38.1 kJ mol^-1, respectively."},{"sec": "Allotropes of carbon","ids": [1054],"t": "Carbon black, coke, charcoal are impure graphite or fullerenes.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Other forms of elemental carbon like carbon black, coke, and charcoal are all impure forms of graphite or fullerenes."},{"sec": "Allotropes of carbon","ids": [1055,1056],"t": "Carbon black: hydrocarbons burnt in limited air. Charcoal and coke: wood or coal heated strongly without air.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Carbon black is obtained by burning hydrocarbons in a limited supply of air. Charcoal and coke are obtained by heating wood or coal respectively at high temperatures in the absence of air."},{"sec": "Uses of carbon","ids": [1056,1057],"t": "Graphite fibres in plastic: strong light composites (rackets, rods, aircraft, canoes).","exc": false,"tab": false,"src": "old11","page": 68,"o": "Graphite fibres embedded in plastic material form high strength, lightweight composites. The composites are used in products such as tennis rackets, fishing rods, aircrafts and canoes."},{"sec": "Uses of carbon","ids": [1058,1059],"t": "Graphite: electrodes (batteries, electrolysis); graphite crucibles inert to dilute acids and alkalies.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Being good conductor, graphite is used for electrodes in batteries and industrial electrolysis. Crucibles made from graphite are inert to dilute acids and alkalies."},{"sec": "Uses of carbon","ids": [1060],"t": "Activated charcoal (porous): adsorbs poisonous gases; water filters; odour control.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Being highly porous, activated charcoal is used in adsorbing poisonous gases; also used in water filters to remove organic contaminators and in airconditioning system to control odour."},{"sec": "Uses of carbon","ids": [1061,1062],"t": "Carbon black: black ink pigment, tyre filler. Coke: fuel and reducing agent in metallurgy.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Carbon black is used as black pigment in black ink and as filler in automobile tyres. Coke is used as a fuel and largely as a reducing agent in metallurgy."},{"sec": "Carbon monoxide","ids": [1064],"t": "2C(s) + O2(g) → 2CO(g) in limited O2.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Direct oxidation of C in limited supply of oxygen or air yields carbon monoxide. 2C(s) + O2(g) → 2CO(g) (∆)"},{"sec": "Carbon monoxide","ids": [1064],"t": "Pure CO: HCOOH → H2O + CO (conc. H2SO4, 373 K)","exc": false,"tab": false,"src": "old11","page": 68,"o": "On small scale pure CO is prepared by dehydration of formic acid with concentrated H2SO4 at 373 K. HCOOH → H2O + CO (373 K, conc. H2SO4)"},{"sec": "Carbon monoxide","ids": [1064,1065,1066],"t": "Water gas (synthesis gas): C(s) + H2O(g) → CO(g) + H2(g) (473–1273 K)","exc": false,"tab": false,"src": "old11","page": 68,"o": "On commercial scale it is prepared by the passage of steam over hot coke. The mixture of CO and H2 thus produced is known as water gas or synthesis gas. C(s) + H2O(g) → CO(g) + H2(g) (473-1273 K)"},{"sec": "Carbon monoxide","ids": [1066],"t": "Producer gas (air instead of steam): 2C + O2 + 4N2 → 2CO + 4N2 (1273 K). Both are industrial fuels.","exc": false,"tab": false,"src": "old11","page": 68,"o": "When air is used instead of steam, a mixture of CO and N2 is produced, which is called producer gas. 2C(s) + O2(g) + 4N2(g) → 2CO(g) + 4N2(g) (1273 K). Water gas and producer gas are very important industrial fuels."},{"sec": "Carbon monoxide","ids": [1067],"t": "Their CO burns further to CO2, releasing heat.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Carbon monoxide in water gas or producer gas can undergo further combustion forming carbon dioxide with the liberation of heat."},{"sec": "Carbon monoxide","ids": [1068,1069],"t": "CO: colourless, odourless, almost insoluble; powerful reductant of almost all metal oxides **except those of alkali and alkaline earth metals, Al and a few transition metals**.","exc": false,"tab": false,"src": "old11","page": 68,"o": "Carbon monoxide is a colourless, odourless and almost water insoluble gas. It is a powerful reducing agent and reduces almost all metal oxides other than those of the alkali and alkaline earth metals, aluminium and a few transition metals."},{"sec": "Carbon monoxide","ids": [1071,1072],"t": "Fe2O3(s) + 3CO(g) → 2Fe(s) + 3CO2(g); ZnO(s) + CO(g) → Zn(s) + CO2(g)","exc": false,"tab": false,"src": "old11","page": 69,"o": "This property of CO is used in the extraction of many metals from their oxides ores. Fe2O3(s) + 3CO(g) → 2Fe(s) + 3CO2(g); ZnO(s) + CO(g) → Zn(s) + CO2(g)"},{"sec": "Carbon monoxide","ids": [1072,1073],"t": ":C≡O: has one σ and two π bonds; the lone pair on C makes CO a donor, forming metal carbonyls.","exc": false,"tab": false,"src": "old11","page": 69,"o": "In CO molecule, there are one sigma and two π bonds between carbon and oxygen, :C≡O:. Because of the presence of a lone pair on carbon, CO molecule acts as a donor and reacts with certain metals when heated to form metal carbonyls."},{"sec": "Carbon monoxide","ids": [1074],"t": "**CO is poisonous: CO–haemoglobin complex is ~300× more stable than O2–haemoglobin**, so blood can't carry O2.","exc": true,"tab": false,"src": "old11","page": 69,"o": "The highly poisonous nature of CO arises because of its ability to form a complex with haemoglobin, which is about 300 times more stable than the oxygen-haemoglobin complex. This prevents haemoglobin in the red blood corpuscles from carrying oxygen round the body and ultimately resulting in death."},{"sec": "Carbon dioxide","ids": [1075,1076],"t": "CO2 from complete combustion: C + O2 → CO2; CH4 + 2O2 → CO2 + 2H2O","exc": false,"tab": false,"src": "old11","page": 69,"o": "It is prepared by complete combustion of carbon and carbon containing fuels in excess of air. C(s) + O2(g) → CO2(g); CH4(g) + 2O2(g) → CO2(g) + 2H2O(g)"},{"sec": "Carbon dioxide","ids": [1076,1077],"t": "Lab: CaCO3(s) + 2HCl(aq) → CaCl2(aq) + CO2(g) + H2O(l). Commercial: heating limestone.","exc": false,"tab": false,"src": "old11","page": 69,"o": "In the laboratory it is conveniently prepared by the action of dilute HCl on calcium carbonate. CaCO3(s) + 2HCl(aq) → CaCl2(aq) + CO2(g) + H2O(l). On commercial scale it is obtained by heating limestone."},{"sec": "Carbon dioxide","ids": [1078,1079],"t": "CO2: colourless, odourless; low water solubility.","exc": false,"tab": false,"src": "old11","page": 69,"o": "It is a colourless and odourless gas. Its low solubility in water makes it of immense biochemical and geo-chemical importance."},{"sec": "Carbon dioxide","ids": [1080],"t": "H2CO3: weak dibasic acid. H2CO3 + H2O ⇌ HCO3^- + H3O^+; HCO3^- + H2O ⇌ CO3^2- + H3O^+","exc": false,"tab": false,"src": "old11","page": 69,"o": "With water, it forms carbonic acid, H2CO3 which is a weak dibasic acid and dissociates in two steps: H2CO3(aq) + H2O(l) ⇌ HCO3^-(aq) + H3O^+(aq); HCO3^-(aq) + H2O(l) ⇌ CO3^2-(aq) + H3O^+(aq)"},{"sec": "Carbon dioxide","ids": [1080],"t": "H2CO3/HCO3^- buffer keeps blood pH at 7.26–7.42.","exc": false,"tab": false,"src": "old11","page": 69,"o": "H2CO3/HCO3^- buffer system helps to maintain pH of blood between 7.26 to 7.42."},{"sec": "Carbon dioxide","ids": [1081],"t": "Acidic: forms carbonates with alkalies.","exc": false,"tab": false,"src": "old11","page": 69,"o": "Being acidic in nature, it combines with alkalies to form metal carbonates."},{"sec": "Carbon dioxide","ids": [1082,1083,1084],"t": "Photosynthesis removes atmospheric CO2 (~0.03%): 6CO2 + 12H2O → C6H12O6 + 6O2 + 6H2O (hν, chlorophyll)","exc": false,"tab": false,"src": "old11","page": 69,"o": "Carbon dioxide, which is normally present to the extent of ~ 0.03 % by volume in the atmosphere, is removed from it by the process known as photosynthesis. 6CO2 + 12H2O → C6H12O6 + 6O2 + 6H2O (hν, chlorophyll)"},{"sec": "Carbon dioxide","ids": [1085,1086,1087],"t": "CO2 isn't poisonous, but rising levels (fossil fuels, limestone for cement) increase the greenhouse effect.","exc": false,"tab": false,"src": "old11","page": 69,"o": "Unlike CO, it is not poisonous. But the increase in combustion of fossil fuels and decomposition of limestone for cement manufacture in recent years seem to increase the CO2 content of the atmosphere. This may lead to increase in green house effect and thus, raise the temperature of the atmosphere which might have serious consequences."},{"sec": "Carbon dioxide","ids": [1088,1089],"t": "Dry ice: liquid CO2 expanded rapidly; refrigerant for ice-cream and frozen food.","exc": false,"tab": false,"src": "old11","page": 69,"o": "Carbon dioxide can be obtained as a solid in the form of dry ice by allowing the liquified CO2 to expand rapidly. Dry ice is used as a refrigerant for ice-cream and frozen food."},{"sec": "Carbon dioxide","ids": [1090,1091,1092],"t": "CO2: carbonating drinks; fire extinguisher (heavy, doesn't support combustion); urea manufacture.","exc": false,"tab": false,"src": "old11","page": 69,"o": "Gaseous CO2 is extensively used to carbonate soft drinks. Being heavy and non-supporter of combustion it is used as fire extinguisher. A substantial amount of CO2 is used to manufacture urea."},{"sec": "Carbon dioxide","ids": [1093,1094,1095],"t": "CO2: C sp; two σ bonds and pπ–pπ bonds to O; **linear, C–O 115 pm (both equal), zero dipole moment**.","exc": false,"tab": false,"src": "old11","page": 69,"o": "In CO2 molecule carbon atom undergoes sp hybridisation. Two sp hybridised orbitals of carbon atom overlap with two p orbitals of oxygen atoms to make two sigma bonds while other two electrons of carbon atom are involved in pπ-pπ bonding with oxygen atom. This results in its linear shape [with both C—O bonds of equal length (115 pm)] with no dipole moment."},{"sec": "Silicon dioxide","ids": [1096],"t": "95% of the earth's crust is silica and silicates.","exc": false,"tab": false,"src": "old11","page": 69,"o": "95% of the earth's crust is made up of silica and silicates."},{"sec": "Silicon dioxide","ids": [1097,1098],"t": "Crystalline silica: quartz, cristobalite, tridymite (interconvertible).","exc": false,"tab": false,"src": "old11","page": 69,"o": "Silicon dioxide, commonly known as silica, occurs in several crystallographic forms. Quartz, cristobalite and tridymite are some of the crystalline forms of silica, and they are interconvertable at suitable temperature."},{"sec": "Silicon dioxide","ids": [1099,1100,1101],"t": "SiO2: covalent 3D network; each Si bonded tetrahedrally to four O; each O to two Si.","exc": false,"tab": false,"src": "old11","page": 69,"o": "Silicon dioxide is a covalent, three-dimensional network solid in which each silicon atom is covalently bonded in a tetrahedral manner to four oxygen atoms. Each oxygen atom in turn covalently bonded to another silicon atoms."},{"sec": "Silicon dioxide","ids": [1102,1103],"t": "Corners shared; giant molecule of 8-membered rings of alternating Si and O.","exc": false,"tab": false,"src": "old11","page": 70,"o": "Each corner is shared with another tetrahedron. The entire crystal may be considered as giant molecule in which eight membered rings are formed with alternate silicon and oxygen atoms."},{"sec": "Silicon dioxide","ids": [1103,1104],"t": "Silica is almost unreactive (very high Si–O bond enthalpy): resists halogens, H2, most acids and metals.","exc": false,"tab": false,"src": "old11","page": 70,"o": "Silica in its normal form is almost nonreactive because of very high Si—O bond enthalpy. It resists the attack by halogens, dihydrogen and most of the acids and metals even at elevated temperatures."},{"sec": "Silicon dioxide","ids": [1105],"t": "**SiO2 is attacked by HF and NaOH**: SiO2 + 2NaOH → Na2SiO3 + H2O; SiO2 + 4HF → SiF4 + 2H2O","exc": true,"tab": false,"src": "old11","page": 70,"o": "However, it is attacked by HF and NaOH. SiO2 + 2NaOH → Na2SiO3 + H2O; SiO2 + 4HF → SiF4 + 2H2O"},{"sec": "Silicon dioxide","ids": [1105],"t": "Quartz: piezoelectric (accurate clocks, radio, TV, mobile communication).","exc": false,"tab": false,"src": "old11","page": 70,"o": "Quartz is extensively used as a piezoelectric material; it has made possible to develop extremely accurate clocks, modern radio and television broadcasting and mobile radio communications."},{"sec": "Silicon dioxide","ids": [1106,1107],"t": "Silica gel: drying agent; chromatography and catalyst support. Kieselghur (amorphous): filtration.","exc": false,"tab": false,"src": "old11","page": 70,"o": "Silica gel is used as a drying agent and as a support for chromatographic materials and catalysts. Kieselghur, an amorphous form of silica is used in filtration plants."},{"sec": "Silicones","ids": [1108],"t": "Silicones: organosilicon polymers with repeating unit (–R2SiO–).","exc": false,"tab": false,"src": "old11","page": 70,"o": "Silicones are a group of organosilicon polymers, which have (-R2SiO-) as a repeating unit."},{"sec": "Silicones","ids": [1109],"t": "Made from RnSiCl(4-n) (R = alkyl or aryl).","exc": false,"tab": false,"src": "old11","page": 70,"o": "The starting materials for the manufacture of silicones are alkyl or aryl substituted silicon chlorides, RnSiCl(4-n), where R is alkyl or aryl group."},{"sec": "Silicones","ids": [1110],"t": "CH3Cl + Si (Cu catalyst, 573 K) → MeSiCl3, Me2SiCl2, Me3SiCl, a little Me4Si.","exc": false,"tab": false,"src": "old11","page": 70,"o": "When methyl chloride reacts with silicon in the presence of copper as a catalyst at a temperature 573K various types of methyl substituted chlorosilane of formula MeSiCl3, Me2SiCl2, Me3SiCl with small amount of Me4Si are formed."},{"sec": "Silicones","ids": [1111],"t": "Hydrolysis of (CH3)2SiCl2 then condensation polymerisation gives straight-chain silicones.","exc": false,"tab": false,"src": "old11","page": 70,"o": "Hydrolysis of dimethyldichlorosilane, (CH3)2SiCl2 followed by condensation polymerisation yields straight chain polymers."},{"sec": "Silicones","ids": [1112],"t": "2CH3Cl + Si → (CH3)2SiCl2 (Cu powder, 570 K); (CH3)2SiCl2 + 2H2O → (CH3)2Si(OH)2 + 2HCl; condensation polymerisation (−H2O) → silicone","exc": false,"tab": true,"src": "old11","page": 70,"o": "2CH3Cl + Si → (CH3)2SiCl2 (Cu powder, 570 K); (CH3)2SiCl2 + 2H2O → (CH3)2Si(OH)2 + 2HCl; condensation polymerisation (−H2O) → silicone"},{"sec": "Silicones","ids": [1112],"t": "**(CH3)3SiCl blocks the chain ends**, controlling chain length.","exc": false,"tab": false,"src": "old11","page": 70,"o": "The chain length of the polymer can be controlled by adding (CH3)3SiCl which blocks the ends."},{"sec": "Silicones","ids": [1113,1114],"t": "Non-polar alkyl surface: water repellent; high thermal stability, high dielectric strength, resistant to oxidation and chemicals.","exc": false,"tab": false,"src": "old11","page": 71,"o": "Silicones being surrounded by non-polar alkyl groups are water repelling in nature. They have in general high thermal stability, high dielectric strength and resistance to oxidation and chemicals."},{"sec": "Silicones","ids": [1116,1117],"t": "Uses: sealants, greases, electrical insulators, waterproofing; biocompatible (surgical and cosmetic implants).","exc": false,"tab": false,"src": "old11","page": 71,"o": "They are used as sealant, greases, electrical insulators and for water proofing of fabrics. Being biocompatible they are also used in surgical and cosmetic plants."},{"sec": "Silicones","ids": [1118,1119],"t": "Simple silicones: (R2SiO)n chains with alkyl or phenyl groups on Si; hydrophobic.","exc": false,"tab": true,"src": "old11","page": 71,"o": "Simple silicones consist of (R2SiO)n chains in which alkyl or phenyl groups occupy the remaining bonding positions on each silicon. They are hydrophobic (water repellant) in nature."},{"sec": "Silicates and zeolites","ids": [1120,1121],"t": "Silicate minerals: feldspar, zeolites, mica, asbestos.","exc": false,"tab": false,"src": "old11","page": 71,"o": "A large number of silicates minerals exist in nature. Some of the examples are feldspar, zeolites, mica and asbestos."},{"sec": "Silicates and zeolites","ids": [1122],"t": "Basic unit: tetrahedral SiO4^4-.","exc": false,"tab": false,"src": "old11","page": 71,"o": "The basic structural unit of silicates is SiO4^4- in which silicon atom is bonded to four oxygen atoms in tetrahedron fashion."},{"sec": "Silicates and zeolites","ids": [1123,1124],"t": "Units are discrete or share 1, 2, 3 or 4 O corners, giving chain, ring, sheet or 3D structures.","exc": false,"tab": false,"src": "old11","page": 71,"o": "In silicates either the discrete unit is present or a number of such units are joined together via corners by sharing 1,2,3 or 4 oxygen atoms per silicate units. When silicate units are linked together, they form chain, ring, sheet or three-dimensional structures."},{"sec": "Silicates and zeolites","ids": [1125,1129,1130],"t": "Negative charge balanced by metal cations; all four corners shared gives a 3D network.","exc": false,"tab": false,"src": "old11","page": 71,"o": "Negative charge on silicate structure is neutralized by positively charged metal ions. If all the four corners are shared with other tetrahedral units, three-dimensional network is formed."},{"sec": "Silicates and zeolites","ids": [1131],"t": "Man-made silicates: glass, cement.","exc": false,"tab": false,"src": "old11","page": 71,"o": "Two important man-made silicates are glass and cement."},{"sec": "Silicates and zeolites","ids": [1132,1133,1134],"t": "Al replacing some Si in the SiO2 network gives negatively charged aluminosilicates (balanced by Na^+, K^+, Ca^2+): feldspar, zeolites.","exc": false,"tab": false,"src": "old11","page": 71,"o": "If aluminium atoms replace few silicon atoms in three-dimensional network of silicon dioxide, overall structure known as aluminosilicate, acquires a negative charge. Cations such as Na^+, K^+ or Ca^2+ balance the negative charge. Examples are feldspar and zeolites."},{"sec": "Silicates and zeolites","ids": [1135],"t": "Zeolites: petrochemical catalysts (cracking, isomerisation); **ZSM-5 converts alcohols directly to gasoline**.","exc": false,"tab": false,"src": "old11","page": 71,"o": "Zeolites are widely used as a catalyst in petrochemical industries for cracking of hydrocarbons and isomerisation, e.g., ZSM-5 (A type of zeolite) used to convert alcohols directly into gasoline."},{"sec": "Silicates and zeolites","ids": [1136],"t": "Hydrated zeolites: ion exchangers for softening hard water.","exc": false,"tab": false,"src": "old11","page": 71,"o": "Hydrated zeolites are used as ion exchangers in softening of \"hard\" water."}]);
})();
